// ---------------------------------------------------------------------------------------------
// SortAggregate
// ---------------------------------------------------------------------------------------------

// SortAggregate requires its input sorted on GroupBy. It streams: one group in memory, emitted
// when the next row's key differs.
type SortAggregate struct {
	Child   Operator
	GroupBy []int
	Aggs    []AggSpec
	Names   []string

	MaxGroups int // always 1 (that's the point)

	cur     *group
	curKey  string
	done    bool
	emitted bool
}

func (s *SortAggregate) Schema() []string { return s.Names }
func (s *SortAggregate) Close()           { s.Child.Close() }
func (s *SortAggregate) Open() {
	s.Child.Open()
	s.cur, s.done, s.emitted = nil, false, false
}

func (s *SortAggregate) Next() (Row, bool) {
	for !s.done {
		r, ok := s.Child.Next()
		if !ok {
			s.done = true
			break
		}
		key := make([]Value, len(s.GroupBy))
		for i, c := range s.GroupBy {
			key[i] = r[c]
		}
		k := groupKey(key)
		if s.cur != nil && k != s.curKey { // key changed: the previous group is complete
			finished := s.cur
			s.cur, s.curKey = newGroup(key, s.Aggs), k
			s.cur.step(r, s.Aggs)
			s.emitted = true
			return finished.row(), true
		}
		if s.cur == nil {
			s.cur, s.curKey, s.MaxGroups = newGroup(key, s.Aggs), k, 1
		}
		s.cur.step(r, s.Aggs)
	}
	// Input exhausted: flush the last group (or the single empty-input row with no GROUP BY).
	if s.cur != nil {
		last := s.cur
		s.cur = nil
		return last.row(), true
	}
	if !s.emitted && len(s.GroupBy) == 0 {
		s.emitted = true
		return newGroup(nil, s.Aggs).row(), true
	}
	return nil, false
}

// ---------------------------------------------------------------------------------------------
// Sorting
// ---------------------------------------------------------------------------------------------

// SortKey is one ORDER BY term.
type SortKey struct {
	Col  int
	Desc bool
}

// CompareRows orders rows by keys. NULLs sort last in both directions (DESIGN.md).
func CompareRows(a, b Row, keys []SortKey) int {
	for _, k := range keys {
		x, y := a[k.Col], b[k.Col]
		var c int
		switch {
		case x == nil && y == nil:
			c = 0
		case x == nil:
			return 1 // NULL last, regardless of Desc
		case y == nil:
			return -1
		default:
			c = Compare(x, y)
			if k.Desc {
				c = -c
			}
		}
		if c != 0 {
			return c
		}
	}
	return 0
}

// Sort reads everything, sorts in memory (stable), and hands rows back.
type Sort struct {
	Child Operator
	Keys  []SortKey
	out   sliceOp
}

func (s *Sort) Schema() []string  { return s.Child.Schema() }
func (s *Sort) Close()            {}
func (s *Sort) Next() (Row, bool) { return s.out.Next() }
func (s *Sort) Open() {
	rows := Collect(s.Child)
	sort.SliceStable(rows, func(i, j int) bool { return CompareRows(rows[i], rows[j], s.Keys) < 0 })
	s.out = sliceOp{cols: s.Child.Schema(), rows: rows}
}

// ExternalSort pretends memory holds only RunSize rows. Phase 1 fills memory, sorts it, and
// "spills" it as a sorted run (here: kept in a slice, standing in for a temp file). Phase 2 merges
// all runs at once with a min-heap holding one row per run — memory = number of runs, not rows.
type ExternalSort struct {
	Child   Operator
	Keys    []SortKey
	RunSize int

	Runs             int // how many sorted runs were spilled
	MergeComparisons int

	runs [][]Row
	pos  []int // next unread index in each run
	h    *mergeHeap
}

func (e *ExternalSort) Schema() []string { return e.Child.Schema() }
func (e *ExternalSort) Close()           { e.runs = nil }

func (e *ExternalSort) Open() {
	// Phase 1: produce sorted runs.
	e.runs = nil
	buf := []Row{}
	spill := func() {
		if len(buf) == 0 {
			return
		}
		sort.SliceStable(buf, func(i, j int) bool { return CompareRows(buf[i], buf[j], e.Keys) < 0 })
		e.runs = append(e.runs, buf)
		buf = []Row{}
	}
	e.Child.Open()
	for {
		r, ok := e.Child.Next()
		if !ok {
			break
		}
		buf = append(buf, r)
		if len(buf) == e.RunSize {
			spill()
		}
	}
	e.Child.Close()
	spill()
	e.Runs = len(e.runs)

	// Phase 2: seed the heap with the head of every run.
	e.pos = make([]int, len(e.runs))
	e.h = &mergeHeap{keys: e.Keys, cmps: &e.MergeComparisons}
	for i, run := range e.runs {
		heap.Push(e.h, cursor{run: i, row: run[0]})
		e.pos[i] = 1
	}
}

