type cursor struct {
	run int
	row Row
}

// mergeHeap is a min-heap of run heads. Ties break on run index, which keeps the merge stable.
type mergeHeap struct {
	items []cursor
	keys  []SortKey
	cmps  *int
}

func (h *mergeHeap) Len() int { return len(h.items) }
func (h *mergeHeap) Less(i, j int) bool {
	*h.cmps++
	if c := CompareRows(h.items[i].row, h.items[j].row, h.keys); c != 0 {
		return c < 0
	}
	return h.items[i].run < h.items[j].run
}
func (h *mergeHeap) Swap(i, j int) { h.items[i], h.items[j] = h.items[j], h.items[i] }
func (h *mergeHeap) Push(x any)    { h.items = append(h.items, x.(cursor)) }
func (h *mergeHeap) Pop() any {
	last := h.items[len(h.items)-1]
	h.items = h.items[:len(h.items)-1]
	return last
}

// TopN is ORDER BY … LIMIT N without sorting everything: keep a heap of the N best rows seen so
// far, with the *worst* of them on top so it can be evicted in O(log N).
type TopN struct {
	Child Operator
	Keys  []SortKey
	N     int

	Evictions int // rows that entered the heap and were later pushed out

	out sliceOp
}

type seqRow struct {
	seq int // arrival order: makes ties stable
	row Row
}

type worstFirst struct {
	items []seqRow
	keys  []SortKey
}

func (w *worstFirst) cmp(a, b seqRow) int {
	if c := CompareRows(a.row, b.row, w.keys); c != 0 {
		return c
	}
	return a.seq - b.seq
}
func (w *worstFirst) Len() int           { return len(w.items) }
func (w *worstFirst) Less(i, j int) bool { return w.cmp(w.items[i], w.items[j]) > 0 } // max-heap
func (w *worstFirst) Swap(i, j int)      { w.items[i], w.items[j] = w.items[j], w.items[i] }
func (w *worstFirst) Push(x any)         { w.items = append(w.items, x.(seqRow)) }
func (w *worstFirst) Pop() any {
	last := w.items[len(w.items)-1]
	w.items = w.items[:len(w.items)-1]
	return last
}

func (t *TopN) Schema() []string  { return t.Child.Schema() }
func (t *TopN) Close()            {}
